SELECT m.id AS wmp_id, p.id AS paper_id, p.symbol, p.entry_price, MIN(e.old_value_usdt) AS first_tp, COUNT(*) AS n_ext, p.exit_price, p.close_reason, ROUND((MIN(e.old_value_usdt)-p.entry_price)/p.entry_price*100,4) AS first_tp_pct, ROUND((p.exit_price-p.entry_price)/p.entry_price*100,4) AS realized_pct, ROUND(p.realized_pnl,6) AS realized_pnl FROM crypto_ai.position_management_event e JOIN crypto_ai.wallet_managed_position m ON m.id=e.wallet_position_id JOIN crypto_ai.paper_position p ON p.signal_id=m.entry_signal_id WHERE e.event_type='TAKE_PROFIT_EXTENDED' AND e.occurred_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) AND p.status='CLOSED' GROUP BY m.id, p.id, p.symbol, p.entry_price, p.exit_price, p.close_reason, p.realized_pnl ORDER BY p.id LIMIT 100;